<?php
declare(strict_types=1);
require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/backup_step18.php';require_once __DIR__.'/config/deployment_step19.php';
$error=null;$success=null;$runs=[];$backups=[];try{$pdo=business_db();deployment_step19_ensure($pdo);backup_step18_ensure($pdo);$user=security_step17_current_user($pdo);$ctx=deployment_step19_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){security_step17_verify_csrf((string)($_POST['csrf']??''));$action=(string)($_POST['action']??'');if($action==='create'){$bid=(int)($_POST['backup_id']??0);deployment_step19_create_migration($pdo,(string)($_POST['target']??'production'),$bid>0?$bid:null,(string)($_POST['notes']??''),(int)$user['id']);$success='Migration plan created.';}elseif($action==='status'){$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'planned');$allowed=['planned','backup_ready','target_ready','restored','validated','completed','failed'];if(!in_array($status,$allowed,true))throw new RuntimeException('Migration status is invalid.');$stmt=$pdo->prepare("UPDATE deployment_migration_runs SET status=?,target_schema_fingerprint=IF(? IN ('validated','completed'),?,target_schema_fingerprint),completed_at=IF(?='completed',NOW(),completed_at) WHERE id=? AND organization_id=?");$schema=backup_step18_schema_fingerprint($pdo);$stmt->execute([$status,$status,$schema,$status,$id,$orgId]);deployment_step19_log($pdo,'migration_status_changed','pass',['migration_id'=>$id,'status'=>$status],(int)$user['id']);$success='Migration status updated.';}}$s=$pdo->prepare("SELECT id,backup_code,created_at,file_sha256,schema_fingerprint FROM backup_records WHERE organization_id=? AND verification_status='verified' AND status<>'expired' ORDER BY id DESC");$s->execute([$orgId]);$backups=$s->fetchAll();$s=$pdo->prepare("SELECT m.*,b.backup_code FROM deployment_migration_runs m LEFT JOIN backup_records b ON b.id=m.backup_record_id WHERE m.organization_id=? ORDER BY m.id DESC LIMIT 100");$s->execute([$orgId]);$runs=$s->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Migration Center - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="deployment_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 19 • Local → Cloud Migration</small></span></a><div class="os-top-actions"><a class="os-btn" href="backup_center.php">Backups</a><a class="os-btn primary" href="deployment_center.php">Deployment</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Migration</div><nav class="os-nav"><a href="deployment_center.php"><i class="dot"></i>Deployment</a><a class="active" href="migration_center.php"><i class="dot"></i>Migration</a><a href="offsite_backup.php"><i class="dot"></i>Offsite</a><a href="step19_audit.php"><i class="dot"></i>Audit</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">ENCRYPTED MIGRATION BOUNDARY</div><h1>Move data with a verified STEP 18 package—not with ad-hoc table copies.</h1><p>The source database is backed up and verified first. The target environment restores the encrypted package, validates schema/data, then the migration is marked complete.</p></section><?php if($error):?><div class="pp-alert bad"><?= deployment_step19_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><?= deployment_step19_h($success) ?></div><?php endif;?><section class="s10-grid"><article class="s10-card s10-span-5"><h2>Create Migration Plan</h2><form method="post"><input type="hidden" name="csrf" value="<?= deployment_step19_h(security_step17_csrf()) ?>"><input type="hidden" name="action" value="create"><label><b>Target environment</b><select name="target" style="width:100%;margin:6px 0 12px"><option value="staging">Staging</option><option value="production" selected>Production</option></select></label><label><b>Verified backup</b><select name="backup_id" style="width:100%;margin:6px 0 12px"><option value="0">Plan first; attach later</option><?php foreach($backups as $b):?><option value="<?= (int)$b['id'] ?>"><?= deployment_step19_h($b['backup_code'].' • '.$b['created_at']) ?></option><?php endforeach;?></select></label><label><b>Notes</b><textarea name="notes" rows="4" style="width:100%;margin-top:6px" placeholder="Hosting/provider notes; never paste secrets here."></textarea></label><button class="os-btn primary" style="margin-top:12px">Create Plan</button></form></article><aside class="s10-card s10-span-7"><h2>Required Sequence</h2><div class="s10-checks"><div class="s10-check good"><div><b>1. Source recovery point</b><span>Create and cryptographically verify an encrypted backup.</span></div><strong>REQUIRED</strong></div><div class="s10-check good"><div><b>2. Deploy code + environment</b><span>Set production secrets on the host; do not upload a .env secret file to Git.</span></div><strong>REQUIRED</strong></div><div class="s10-check good"><div><b>3. Restore preview</b><span>Target schema fingerprint must match the package.</span></div><strong>REQUIRED</strong></div><div class="s10-check good"><div><b>4. Restore + health validation</b><span>Run STEP 18 restore, then STEP 19 production health.</span></div><strong>REQUIRED</strong></div><div class="s10-check good"><div><b>5. Multi-device smoke test</b><span>Login, permissions, sales, backup and session revoke from secure HTTPS devices.</span></div><strong>REQUIRED</strong></div></div></aside></section><section class="s10-card" style="margin-top:14px"><h2>Migration Runs</h2><div class="s10-list"><?php if(!$runs):?><div class="pp-alert">No migration plan yet. Local-only operation is still valid.</div><?php endif;?><?php foreach($runs as $r):?><div class="s10-row"><div><b><?= deployment_step19_h($r['migration_code']) ?> • <?= deployment_step19_h(strtoupper($r['source_environment'].' → '.$r['target_environment'])) ?></b><small><?= deployment_step19_h($r['backup_code']?:'No backup attached') ?> • <?= deployment_step19_h($r['started_at']) ?></small></div><form method="post" style="display:flex;gap:8px;align-items:center"><input type="hidden" name="csrf" value="<?= deployment_step19_h(security_step17_csrf()) ?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><select name="status"><?php foreach(['planned','backup_ready','target_ready','restored','validated','completed','failed'] as $st):?><option <?= $r['status']===$st?'selected':'' ?>><?= $st ?></option><?php endforeach;?></select><button class="os-btn">Update</button></form></div><?php endforeach;?></div></section></main></div></body></html>